#!/usr/bin/env python3
"""HomeMind ESP32-S3-EYE serial console driver (runs on Ubuntu build host).

Usage:
  python3 hm_ser.py <script.json>

script.json = {"port": null|"/dev/ttyACM1", "baud":115200,
               "steps":[{"send":"...", "wait":2.0}, {"drain":6.0}, ...],
               "boot_wait": 3.0}

Prints a transcript with markers. Always terminates.
"""
import sys
import os
import time
import glob
import select
import json

try:
    import serial
except ImportError:
    sys.exit("pyserial missing")


def log(*a):
    print(*a, flush=True)


def find_port():
    for p in sorted(glob.glob('/dev/ttyACM*')):
        try:
            s = serial.Serial(p, 115200, timeout=0)
            s.close()
            return p
        except Exception:
            pass
    return None


def main():
    arg = sys.argv[1]
    cfg = json.loads(arg) if arg.lstrip().startswith('{') else json.load(open(arg))
    port = cfg.get('port') or find_port()
    if not port:
        sys.exit("no serial port")
    baud = cfg.get('baud', 115200)
    s = serial.Serial(port, baud, timeout=0)
    fd = s.fileno()
    log("### PORT %s @%d" % (port, baud))

    def drain(sec):
        end = time.time() + sec
        buf = b''
        while time.time() < end:
            r, _, _ = select.select([fd], [], [], 0.3)
            if fd in r:
                try:
                    d = os.read(fd, 8192)
                    if d:
                        buf += d
                except Exception:
                    pass
        return buf

    if cfg.get('boot_wait'):
        drain(cfg['boot_wait'])

    for st in cfg.get('steps', []):
        if 'send' in st:
            s.write(st['send'].encode() + b'\r\n')
            log("### SEND %r" % st['send'])
        w = st.get('wait', st.get('drain', 1.0))
        out = drain(w)
        txt = out.decode('utf-8', 'replace')
        if txt.strip():
            log(txt)
    s.close()
    log("### END")

