 * Private Functions - imgsensor ops (OV2640 sensor control)
 ****************************************************************************/

static bool ov2640_is_available(FAR struct imgsensor_s* sensor)
{
    return true;
}

static void ov2640_start_xclk(void)
{
    FAR struct pwm_lowerhalf_s *pwm;
    struct pwm_info_s info;
    printf("[CAM-SENSOR] xclk_init_enter\n");
    fflush(stdout);
    pwm = esp32s3_ledc_init(0);
    printf("[CAM-SENSOR] xclk_init_exit pwm=%p\n", pwm);
    fflush(stdout);
    if (pwm == NULL) {
        syslog(LOG_ERR, "CAM: LEDC init failed\n");
        return;
    }

    printf("[CAM-SENSOR] xclk_setup_enter\n");
    fflush(stdout);
    pwm->ops->setup(pwm);
    printf("[CAM-SENSOR] xclk_setup_exit\n");
    fflush(stdout);

    info.frequency = 20000000;
    info.duty = (ub16_t)(65536 / 2);

    printf("[CAM-SENSOR] xclk_start_enter\n");
    fflush(stdout);
    pwm->ops->start(pwm, &info);
    printf("[CAM-SENSOR] xclk_start_exit\n");
    fflush(stdout);
    syslog(LOG_INFO, "CAM: LEDC XCLK 20MHz started on GPIO15\n");
}

static int ov2640_init(FAR struct imgsensor_s* sensor)
{
    FAR struct i2c_master_s* i2c;
    int ret;
    printf("[CAM-SENSOR] init_enter\n");
    fflush(stdout);
    ov2640_start_xclk();
    printf("[CAM-SENSOR] xclk_done\n");
    fflush(stdout);
    syslog(LOG_INFO, "CAM: LEDC XCLK started on GPIO15\n");
    up_mdelay(50);

    printf("[CAM-SENSOR] i2c_init_enter\n");
    fflush(stdout);
    i2c = esp32s3_i2cbus_initialize(OV2640_I2C_BUS);
    printf("[CAM-SENSOR] i2c_init_exit i2c=%p\n", i2c);
    fflush(stdout);
    if (i2c == NULL) {
        return -ENODEV;
    }

    /* 1. Soft reset */

    printf("[CAM-SENSOR] reset_regs_enter\n");
    fflush(stdout);
    ret = WRITE_REGS(i2c, g_ov2640_reset);
    printf("[CAM-SENSOR] reset_regs_exit ret=%d\n", ret);
    fflush(stdout);
    if (ret < 0) {
        return ret;
    }

    up_mdelay(10);

    /* 2. CIF base config (full sensor + DSP init) */

    printf("[CAM-SENSOR] cif_base_enter\n");
    fflush(stdout);
    ret = WRITE_REGS(i2c, g_ov2640_cif_base);
    printf("[CAM-SENSOR] cif_base_exit ret=%d\n", ret);
    fflush(stdout);
    if (ret < 0) {
        return ret;
    }
    /* 3. CIF mode transition (DSP window + CTRL2/CTRLI) */

    printf("[CAM-SENSOR] to_cif_enter\n");
    fflush(stdout);
    ret = WRITE_REGS(i2c, g_ov2640_to_cif);
    printf("[CAM-SENSOR] to_cif_exit ret=%d\n", ret);
    fflush(stdout);
    if (ret < 0) {
        return ret;
    }

    /* 4. QVGA zoom window */

    printf("[CAM-SENSOR] qvga_enter\n");
    fflush(stdout);
    ret = WRITE_REGS(i2c, g_ov2640_qvga_window);
    printf("[CAM-SENSOR] qvga_exit ret=%d\n", ret);
    fflush(stdout);
    if (ret < 0) {
        return ret;
    }

    /* 5. Clock config */

    printf("[CAM-SENSOR] clock_enter\n");
    fflush(stdout);
    ret = WRITE_REGS(i2c, g_ov2640_clock);
    printf("[CAM-SENSOR] clock_exit ret=%d\n", ret);
    fflush(stdout);
    if (ret < 0) {
        return ret;
    }

    /* 6. Enable DSP */

    printf("[CAM-SENSOR] dsp_enter\n");
    fflush(stdout);
    ret = WRITE_REGS(i2c, g_ov2640_dsp_en);
    printf("[CAM-SENSOR] dsp_exit ret=%d\n", ret);
    fflush(stdout);
    if (ret < 0) {
        return ret;
    }
    up_mdelay(10);

    /* 7. RGB565 output format */

    printf("[CAM-SENSOR] rgb565_enter\n");
    fflush(stdout);
    ret = WRITE_REGS(i2c, g_ov2640_rgb565);
    printf("[CAM-SENSOR] rgb565_exit ret=%d\n", ret);
    fflush(stdout);
    if (ret < 0) {
        return ret;
    }

    syslog(LOG_INFO, "OV2640 sensor configured for QVGA RGB565\n");
    return OK;
}

