static int capture_open(FAR struct file *filep)
{
  FAR struct inode *inode = filep->f_inode;
  FAR capture_mng_t *cmng = inode->i_private;
  int ret = OK;

  if (cmng == NULL)
    {
      return -EINVAL;
    }

  printf("[CAM-OPEN] mutex_enter\n");
  fflush(stdout);
  nxmutex_lock(&cmng->mutex);
  printf("[CAM-OPEN] mutex_locked open_num=%u\n", cmng->open_num);
  fflush(stdout);
  if (cmng->open_num == 0)
    {
      /* Only in first execution, open device */

      printf("[CAM-OPEN] sensor_init_enter\n");
      fflush(stdout);
      ret = IMGSENSOR_INIT(cmng->imgsensor);
      printf("[CAM-OPEN] sensor_init_exit ret=%d errno=%d\n", ret, errno);
      fflush(stdout);
      if (ret == OK)
        {
          printf("[CAM-OPEN] imgdata_init_enter\n");
          fflush(stdout);
          ret = IMGDATA_INIT(cmng->imgdata);
          printf("[CAM-OPEN] imgdata_init_exit ret=%d errno=%d\n", ret, errno);
          fflush(stdout);
          if (ret == OK)
            {
              printf("[CAM-OPEN] resources_enter\n");
              fflush(stdout);
              initialize_resources(cmng);
              printf("[CAM-OPEN] resources_exit\n");
              fflush(stdout);
            }
        }
      else
        {
          ret = -ENODEV;
        }
    }

  /* In second or later execution, ret is initial value(=OK) */

  if (ret == OK)
    {
      cmng->open_num++;
    }

