import serial, select, os, time, glob

def log(*a):
    print(*a, flush=True)

def find_port():
    for p in sorted(glob.glob('/dev/ttyACM*')):
        try:
            s = serial.Serial(p, 115200, timeout=0)
            s.close()
            return p
        except Exception:
            pass
    return None

port = find_port()
log("PORT=%s" % port)
s = serial.Serial(port, 115200, timeout=0)
fd = s.fileno()

def drain(sec):
    end = time.time() + sec
    buf = b''
    while time.time() < end:
        r, _, _ = select.select([fd], [], [], 0.5)
        if fd in r:
            try:
                d = os.read(fd, 4096)
                if d:
                    buf += d
            except Exception:
                pass
    return buf

time.sleep(3)
log("=== boot 15s ===")
log(drain(15).decode(errors='replace'))
s.close()
log("=== DONE ===")

